-- Run manually after setting Vault secrets collector_url and collector_token.
-- collector_url: https://YOUR_PROJECT.supabase.co/functions/v1/collect-market-data
-- collector_token was generated by the migration. Never expose it to Vite.
SELECT cron.schedule('collect-market-data','0 * * * *',$cron$
SELECT net.http_post(
 url := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name='collector_url'),
 headers := jsonb_build_object('Content-Type','application/json','x-collector-token',
  (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name='collector_token')),
 body := '{}'::jsonb, timeout_milliseconds := 150000
);$cron$);
